-- T-B-04：作品目录持久化扩展列（内存目录 → PostgreSQL 数据面）
alter table sanye_anime add column if not exists score double precision not null default 0;
alter table sanye_anime add column if not exists update_text varchar(50);
alter table sanye_anime add column if not exists tags_json jsonb not null default '[]'::jsonb;
alter table sanye_anime add column if not exists characters_json jsonb not null default '[]'::jsonb;

create sequence if not exists sanye_anime_id_seq;
alter table sanye_anime alter column id set default nextval('sanye_anime_id_seq');
select setval('sanye_anime_id_seq', coalesce((select max(id) from sanye_anime), 1), true);

-- 种子目录（15 部，对齐 AnimeMemoryStore；幂等：已存在不覆盖）
on conflict (id) do nothing;
